import { PaletteOptions } from "@mui/material/styles";

const palette: PaletteOptions = {
  mode: "light",

  primary: {
    main: "#0D63F4",
    light: "#4F8EF8",
    dark: "#0849B7",
    contrastText: "#FFFFFF",
  },

  secondary: {
    main: "#1E88E5",
  },

  success: {
    main: "#16A34A",
  },

  warning: {
    main: "#F59E0B",
  },

  error: {
    main: "#DC2626",
  },

  info: {
    main: "#2563EB",
  },

  background: {
    default: "#F4F7FB",
    paper: "#FFFFFF",
  },

  text: {
    primary: "#172B4D",
    secondary: "#6B7280",
  },

  divider: "#E5E7EB",

  grey: {
    50: "#F9FAFB",
    100: "#F3F4F6",
    200: "#E5E7EB",
    300: "#D1D5DB",
    400: "#9CA3AF",
    500: "#6B7280",
    600: "#4B5563",
    700: "#374151",
    800: "#1F2937",
    900: "#111827",
  },
};

export default palette;
